UML Generator.class_diagram:
classDiagram
    class LibrarySystem {
        +search()
        +borrow()
        +return()
        +renew()
    }
    class Catalog {
        +findBook()
    }
    class Book {
        -title
        -author
        -status
    }
    class Member {
        -memberId
        -name
    }
    class Loan {
        -dueDate
        -status
    }
    class Fine {
        -amount
    }
    LibrarySystem --> Catalog
    LibrarySystem --> Book
    LibrarySystem --> Member
    LibrarySystem --> Loan
    LibrarySystem --> Fine
    Member "1" --> "*" Loan
    Loan "*" --> "1" Book
    Loan "0..1" --> "0..1" Fine

